// ---- Book M-Room: validate the room and set up its hold config ----
// This tool is ONLY for the three held booths: M2, M6, M7. Ordinary booths
// (M1/M3/M4/M5/M8) and every other room go through Book Session as before.
const ROOMS = {
  M2: { holdOwner: 'Peemo Morato',            approverName: 'Peemo Morato', resource: 'c_1883ui6lnfc9ogt2hrmg57a30n72q@resource.calendar.google.com', holdWords: ['peemo'] },
  M6: { holdOwner: 'Marketing',            approverName: 'Nicole Miller', resource: 'c_188f9gnq0a9tehf4g9ja57l83c0ts@resource.calendar.google.com', holdWords: ['marketing'] },
  M7: { holdOwner: 'Business Development (BD)', approverName: 'Ana Cadelina', resource: 'c_1880r9hhk9c2agpbko87o7fojosh0@resource.calendar.google.com', holdWords: ['bd', 'business development'] }
};

const ZONE = 'Asia/Manila';
const inp = $input.first().json;
const room = String(inp.room || '').trim().toUpperCase();
const cfg = ROOMS[room];

if (!cfg) {
  return [{ json: { terminate: true, status: 'WRONG_TOOL', human: 'Book M-Room only handles M2, M6 and M7. Use Book Session for ' + (room || 'that room') + '.' } }];
}

const allDay = inp.all_day === true || inp.all_day === 'true';
const dateIso = String(inp.start_iso || '').slice(0, 10);
const bookingStart = allDay
  ? DateTime.fromISO(dateIso, { zone: ZONE }).startOf('day')
  : DateTime.fromISO(String(inp.start_iso), { zone: ZONE });
if (!bookingStart.isValid) {
  return [{ json: { terminate: true, status: 'BAD_INPUT', human: 'I could not read the date/time for that ' + room + ' booking.' } }];
}
const now = DateTime.now().setZone(ZONE);
if (bookingStart < now.startOf('day')) {
  return [{ json: { terminate: true, status: 'BLOCKED', human: 'That date has already passed — send me the correct date and I\'ll book ' + room + '.' } }];
}

const bookingEnd = allDay
  ? DateTime.fromISO(dateIso, { zone: ZONE }).plus({ days: 1 }).startOf('day')
  : DateTime.fromISO(String(inp.end_iso), { zone: ZONE });

return [{ json: {
  terminate: false,
  room,
  holdOwner: cfg.holdOwner,
  approverName: cfg.approverName,
  resource: cfg.resource,
  holdWords: cfg.holdWords,
  summary: inp.summary || (room + ' - booking'),
  description: inp.description || '',
  requesterName: inp.requester_name || 'the requester',
  requesterSlackId: inp.requester_slack_id || '',
  allDay,
  dateIso,
  startIso: allDay ? dateIso : String(inp.start_iso),
  endIso: allDay ? bookingEnd.toISODate() : String(inp.end_iso),
  windowStartIso: bookingStart.toISO(),
  windowEndIso: bookingEnd.toISO(),
  bookingDateHuman: bookingStart.toFormat('cccc, MMMM d, yyyy'),
  timeHuman: allDay ? 'All day' : (bookingStart.toFormat('h:mm a') + ' – ' + bookingEnd.toFormat('h:mm a'))
} }];

// Decide the mode by looking at what is on this room for the window:
//  - a standing hold overlaps            -> 'approval' (shared use, needs the approver)
//  - some OTHER booking overlaps          -> 'taken'    (ordinary conflict)
//  - nothing overlaps                     -> 'book'     (ordinary M-booth booking)
const c = $('Classify').item.json;
const ZONE = 'Asia/Manila';
const room = c.room;
const holdWords = c.holdWords || [];
const reqStart = DateTime.fromISO(c.windowStartIso, { zone: ZONE });
const reqEnd = DateTime.fromISO(c.windowEndIso, { zone: ZONE });

const events = $input.all().map(i => i.json).filter(e => e && (e.summary || e.start));
let holdHit = false, otherHit = null;
for (const e of events) {
  const title = String(e.summary || '').trim();
  if (!new RegExp('^' + room + '\\b', 'i').test(title)) continue; // this room only
  const es = e.start && (e.start.dateTime || e.start.date);
  const ee = e.end && (e.end.dateTime || e.end.date);
  if (!es || !ee) continue;
  const s = DateTime.fromISO(String(es), { zone: ZONE });
  const en = DateTime.fromISO(String(ee), { zone: ZONE });
  if (!(s < reqEnd && en > reqStart)) continue; // overlap only
  const lower = title.toLowerCase();
  if (holdWords.some(w => lower.includes(w))) { holdHit = true; }
  else { otherHit = title; }
}

let mode;
if (otherHit) mode = 'taken';
else if (holdHit) mode = 'approval';
else mode = 'book';

return [{ json: Object.assign({}, c, { mode, conflictTitle: otherHit || '' }) }];
